#include <bits/stdc++.h>
using namespace std;

// compressed length of a run of v equal letters
static int cost(int v) {
    if (v < 2) return v;
    int digits = 0;
    for (; v; v /= 10) digits++;
    return digits + 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int k;
    string s;
    cin >> k >> s;
    int n = s.size();
    // prefix/suffix compressed lengths and the run lengths touching each boundary
    vector<int> prefix(n + 1, 0), suffix(n + 1, 0), left(n + 1, 0), right(n + 1, 0);
    for (int i = 0; i < n; i++) {
        int run = i && s[i] == s[i - 1] ? left[i] : 0;
        left[i + 1] = run + 1;
        prefix[i + 1] = prefix[i] + cost(run + 1) - cost(run);
    }
    for (int i = n - 1; i >= 0; i--) {
        int run = i + 1 < n && s[i] == s[i + 1] ? right[i + 1] : 0;
        right[i] = run + 1;
        suffix[i] = suffix[i + 1] + cost(run + 1) - cost(run);
    }
    int answer = n;
    for (int l = 0; l + k <= n; l++) {
        int r = l + k, value = prefix[l] + suffix[r];
        if (l && r < n && s[l - 1] == s[r]) value += cost(left[l] + right[r]) - cost(left[l]) - cost(right[r]);
        answer = min(answer, value);
    }
    cout << answer << "\n";
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    // compressed length of a run of v equal letters
    static int cost(int v) {
        if (v < 2) return v;
        int digits = 0;
        for (; v > 0; v /= 10) digits++;
        return digits + 1;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int k = nextInt();
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        int n = pos - start;
        byte[] s = new byte[n];
        System.arraycopy(buf, start, s, 0, n);
        // prefix/suffix compressed lengths and the run lengths touching each boundary
        int[] prefix = new int[n + 1], suffix = new int[n + 1], left = new int[n + 1], right = new int[n + 1];
        for (int i = 0; i < n; i++) {
            int run = i > 0 && s[i] == s[i - 1] ? left[i] : 0;
            left[i + 1] = run + 1;
            prefix[i + 1] = prefix[i] + cost(run + 1) - cost(run);
        }
        for (int i = n - 1; i >= 0; i--) {
            int run = i + 1 < n && s[i] == s[i + 1] ? right[i + 1] : 0;
            right[i] = run + 1;
            suffix[i] = suffix[i + 1] + cost(run + 1) - cost(run);
        }
        int answer = n;
        for (int l = 0; l + k <= n; l++) {
            int r = l + k, value = prefix[l] + suffix[r];
            if (l > 0 && r < n && s[l - 1] == s[r]) value += cost(left[l] + right[r]) - cost(left[l]) - cost(right[r]);
            answer = Math.min(answer, value);
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

// compressed length of a run of v equal letters
func cost(v int) int {
	if v < 2 {
		return v
	}
	digits := 0
	for ; v > 0; v /= 10 {
		digits++
	}
	return digits + 1
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	k := int(nextInt())
	s := next()
	n := len(s)
	// prefix/suffix compressed lengths and the run lengths touching each boundary
	prefix := make([]int32, n+1)
	suffix := make([]int32, n+1)
	left := make([]int32, n+1)
	right := make([]int32, n+1)
	for i := 0; i < n; i++ {
		run := 0
		if i > 0 && s[i] == s[i-1] {
			run = int(left[i])
		}
		left[i+1] = int32(run + 1)
		prefix[i+1] = prefix[i] + int32(cost(run+1)-cost(run))
	}
	for i := n - 1; i >= 0; i-- {
		run := 0
		if i+1 < n && s[i] == s[i+1] {
			run = int(right[i+1])
		}
		right[i] = int32(run + 1)
		suffix[i] = suffix[i+1] + int32(cost(run+1)-cost(run))
	}
	answer := n
	for l := 0; l+k <= n; l++ {
		r := l + k
		value := int(prefix[l] + suffix[r])
		if l > 0 && r < n && s[l-1] == s[r] {
			value += cost(int(left[l]+right[r])) - cost(int(left[l])) - cost(int(right[r]))
		}
		answer = min(answer, value)
	}
	fmt.Println(answer)
}
